#include &lt;iostream&gt;
#include &lt;memory&gt;
#include &lt;vector&gt;

struct Resource {
    Resource(int v) : value(v) {
        std::cout &lt;&lt; "构造 Resource, value = " &lt;&lt; value &lt;&lt; std::endl;
    }
    ~Resource() {
        std::cout &lt;&lt; "析构 Resource, value = " &lt;&lt; value &lt;&lt; std::endl;
    }
    int value;
};

int main() {
    std::cout &lt;&lt; "== unique_ptr 示例 ==\n";
    {
        // 创建 unique_ptr，通过 make_unique 更安全
        auto up = std::make_unique&lt;Resource&gt;(10);
        std::cout &lt;&lt; "up-&gt;value = " &lt;&lt; up-&gt;value &lt;&lt; std::endl;

        // 无法复制，只能移动所有权
        // auto up2 = up; // 编译错误
        auto up2 = std::move(up);
        if (!up) {
            std::cout &lt;&lt; "up 已为空，所有权转移给 up2" &lt;&lt; std::endl;
        }
        // up2 离开作用域后自动删除 Resource
    }

    std::cout &lt;&lt; "\n== shared_ptr &amp; weak_ptr 示例 ==\n";
    {
        // 创建 shared_ptr，通过 make_shared 更高效
        auto sp1 = std::make_shared&lt;Resource&gt;(20);
        std::cout &lt;&lt; "sp1.use_count() = " &lt;&lt; sp1.use_count() &lt;&lt; std::endl;

        {
            auto sp2 = sp1; // 共享所有权，引用计数加 1
            std::cout &lt;&lt; "sp1.use_count() = " &lt;&lt; sp1.use_count() &lt;&lt; std::endl;

            // 创建 weak_ptr，不增加引用计数
            std::weak_ptr&lt;Resource&gt; wp = sp1;
            std::cout &lt;&lt; "wp.expired()? " &lt;&lt; std::boolalpha &lt;&lt; wp.expired() &lt;&lt; std::endl;

            if (auto temp = wp.lock()) {
                std::cout &lt;&lt; "通过 weak_ptr 获得临时 shared_ptr, value = " &lt;&lt; temp-&gt;value &lt;&lt; std::endl;
            }
            // sp2 离开内层作用域后引用计数减 1
        }

        std::cout &lt;&lt; "sp1.use_count() = " &lt;&lt; sp1.use_count() &lt;&lt; std::endl;
        // sp1 离开作用域后，引用计数为 0，Resource 被析构
    }

    std::cout &lt;&lt; "\n== shared_ptr 循环引用示例（避免使用 weak_ptr 会泄漏） ==\n";
    struct Node {
        int id;
        std::shared_ptr&lt;Node&gt; next;
        std::weak_ptr&lt;Node&gt; prev; // 用 weak_ptr 避免循环引用
        Node(int i) : id(i) {
            std::cout &lt;&lt; "构造 Node " &lt;&lt; id &lt;&lt; std::endl;
        }
        ~Node() {
            std::cout &lt;&lt; "析构 Node " &lt;&lt; id &lt;&lt; std::endl;
        }
    };

    {
        auto n1 = std::make_shared&lt;Node&gt;(1);
        auto n2 = std::make_shared&lt;Node&gt;(2);
        n1-&gt;next = n2;       // n1 持有 n2
        n2-&gt;prev = n1;       // n2 引用 n1，但为 weak_ptr，不增加引用计数

        // 离开作用域后，n2、n1 的引用计数都能归零，依次析构
    }

    std::cout &lt;&lt; "程序结束\n";
    return 0;
}

