 // 创建 ThreadLocal 实例（静态变量避免重复创建）
 private static final ThreadLocal&lt;Integer&gt; threadLocal = ThreadLocal.withInitial(() -&gt; 0);

 public static void main(String[] args) {
     // 设置值
     threadLocal.set(100);
     // 获取值
     System.out.println(threadLocal.get()); // 输出 100
     // 移除值（防止内存泄漏）
     threadLocal.remove();
