 Node&lt;K,V&gt;[] tab = table;
 int n = tab.length, i = (n - 1) &amp; hash;
 Node&lt;K,V&gt; f = tabAt(tab, i);
 if (f == null) {
     if (casTabAt(tab, i, null, new Node&lt;&gt;(hash, key, value))) // CAS 插入空节点
         return null;
