// ------ 线程示例：计算斐波那契（CPU 密集） ------
long fib(long n) {
    if (n &lt; 2) return n;
    return fib(n-1) + fib(n-2);
}

std::mutex mtx;
void threadTask(int id, long n) {
    auto result = fib(n);
    std::lock_guard&lt;std::mutex&gt; lg(mtx);
    std::cout &lt;&lt; "线程 " &lt;&lt; id &lt;&lt; " 计算 fib(" &lt;&lt; n &lt;&lt; ") = "
              &lt;&lt; result &lt;&lt; std::endl;
}

