            &lt;slot&gt;&lt;/slot&gt; &lt;!-- 默认插槽 --&gt;
          &lt;/div&gt;
          &lt;div class="modal-footer" v-if="$slots.footer"&gt;
            &lt;slot name="footer"&gt;&lt;/slot&gt;
          &lt;/div&gt;
        &lt;/div&gt;
      &lt;/div&gt;
    &lt;/transition&gt;
  &lt;/Teleport&gt;
