    MyBuffer buf2 = std::move(buf1); // buf1 转右值，调用移动构造
    MyBuffer buf3(3);                // 再创建一个 buf3
    buf3 = std::move(buf2);          // 调用移动赋值运算符，将 buf2 资源搬移给 buf3

    return 0;
}

