    std::cout &lt;&lt; "sizeof(arr) = " &lt;&lt; sizeof(arr) &lt;&lt; "\n"; // 指针大小
    std::cout &lt;&lt; "strlen(arr) = " &lt;&lt; strlen(arr) &lt;&lt; "\n"; // 字符串长度
}




