// 修饰虚函数，禁止子类覆写
struct Base {
    virtual void foo() {
        std::cout &lt;&lt; "Base::foo()" &lt;&lt; std::endl;
    }
    virtual void bar() final {   // foo() 可以被覆写，但 bar() 被锁定
        std::cout &lt;&lt; "Base::bar() [final]" &lt;&lt; std::endl;
    }
};

struct Derived1 : Base {
    void foo() override {       // 合法：foo() 未被锁定
        std::cout &lt;&lt; "Derived1::foo()" &lt;&lt; std::endl;
    }
    // void bar() override {}   // 错误：bar() 在 Base 中已标记为 final
};

struct Derived2 : Derived1 {
    void foo() override {       // 合法：foo() 在 Derived1 中未加 final
        std::cout &lt;&lt; "Derived2::foo()" &lt;&lt; std::endl;
    }
    // void bar() override {}   // 同样错误：bar() 已被锁定在 Base
};

// 修饰类，禁止继承
class NoMoreDerived final {
public:
    void baz() {
        std::cout &lt;&lt; "NoMoreDerived::baz()" &lt;&lt; std::endl;
    }
};

// class Attempt : public NoMoreDerived { };  // 错误：NoMoreDerived 已标记为 final，无法被继承

int main() {
    Base* p = new Derived1();
    p-&gt;foo();   // 调用 Derived1::foo()
    p-&gt;bar();   // 调用 Base::bar()

    Derived2 d2;
    d2.foo();   // 调用 Derived2::foo()
    d2.bar();   // 仍然是 Base::bar()

    NoMoreDerived nm;
    nm.baz();   // 调用 NoMoreDerived::baz()

    delete p;
    return 0;
}

/*
运行结果：
Derived1::foo()
Base::bar() [final]
Derived2::foo()
Base::bar() [final]
NoMoreDerived::baz()
*/

	代码中：



		Base::bar()前加了final，导致任何子类都无法覆写bar()，尝试写override都会在编译期报错。


		Derived1和Derived2可以覆写foo()，因为它未被锁定；但无论层级多深，bar()都始终调用Base的实现。


		类NoMoreDerived标记为final，因此任何地方尝试从它继承都会编译失败，确保它的接口和行为不被破坏。

