void* vp = static_cast&lt;void*&gt;(ip);
int* ip2 = static_cast&lt;int*&gt;(vp);





	dynamic_cast 




			用途：在运行时检查指针或引用是否指向某个派生类型，仅适用于含有虚函数的多态类型。若转换不合法，对指针返回nullptr，对引用抛出&nbsp;std::bad_cast。




			适用场景：




					向下转型时需要安全检查：当你手头只有基类指针/引用，需要判断它到底指向哪个真正类型，并在转换前做安全验证：

struct Base { virtual ~Base() = default; };
struct DerivedA : Base { void fooA() {} };
struct DerivedB : Base { void fooB() {} };

void process(Base* b) {
    if (DerivedA* da = dynamic_cast&lt;DerivedA*&gt;(b)) {
        da-&gt;fooA();  // 确保 b 真正指向 DerivedA
    } else if (DerivedB* db = dynamic_cast&lt;DerivedB*&gt;(b)) {
        db-&gt;fooB();  // 确保 b 真正指向 DerivedB
    }
}



					使用引用时的异常安全：

void handle(Base&amp; br) {
    try {
        DerivedA&amp; ra = dynamic_cast&lt;DerivedA&amp;&gt;(br);
        ra.fooA();
    } catch (const std::bad_cast&amp;) {
        // 不是 DerivedA 类型
    }
}



					在多重继承或虚继承场景，dynamic_cast会正确处理调整指针偏移。






	const_cast 




			用途：仅用于添加或移除const/volatile限定，不做其他类型转换，也不改变底层对象布局。通常用于调用需要非const参数的接口或绕过编译时常量检查。




			适用场景：




					移除常量以调用老旧 API，但如果原始对象确实是常量（如字符串字面量），修改它会导致未定义行为，故需谨慎：

void legacyFunction(char* s);

void wrapper(const char* s) {
