};

struct DerivedB : Base {
    void fooB() { std::cout &lt;&lt; "DerivedB::fooB()\n"; }
};

void staticCastDemo() {
    // static_cast：基类↔派生类指针转换（需确保类型安全）
    Base* b1 = new DerivedA;
    DerivedA* da = static_cast&lt;DerivedA*&gt;(b1);  // 假定 b1 真正指向 DerivedA
