    int* ip = new int(42);
    void* vp = static_cast&lt;void*&gt;(ip);
    int* ip2 = static_cast&lt;int*&gt;(vp);
    std::cout &lt;&lt; "*ip2 = " &lt;&lt; *ip2 &lt;&lt; "\n";
    delete ip2;
}

void dynamicCastDemo() {
    Base* b2 = new DerivedB;
