    // 移除 const 调用需非常量接口（不建议修改 s 内容，否则未定义）
    char* p = const_cast&lt;char*&gt;(s);
    std::cout &lt;&lt; "原始字符串: " &lt;&lt; p &lt;&lt; "\n";
    // p[0] = 'h'; // 若执行会导致未定义行为，因为 s 指向文字常量
