    staticCastDemo();

    std::cout &lt;&lt; "\n---- dynamic_cast 示例 ----\n";
    dynamicCastDemo();

    std::cout &lt;&lt; "\n---- const_cast 示例 ----\n";
    constCastDemo();

    std::cout &lt;&lt; "\n---- reinterpret_cast 示例 ----\n";
    reinterpretCastDemo();

