    // 线程A持有锁
}
// 线程B尝试进入同步块时被阻塞（BLOCKED）           RUNNABLE → WAITING     synchronized (lock) {
    lock.wait(); // 释放锁，进入 WAITING
}           RUNNABLE → TIMED_WAITING     Thread.sleep(1000); // 进入 TIMED_WAITING           WAITING → RUNNABLE     synchronized (lock) {
    lock.notify(); // 唤醒等待线程
}           RUNNABLE → TERMINATED     thread.run() 执行完毕或抛出异常。

