  Semaphore filledSlots = new Semaphore(0);

  // 生产者
  void produce() throws InterruptedException {
      emptySlots.acquire();
      addToBuffer();
      filledSlots.release();
  }

  // 消费者
  void consume() throws InterruptedException {
      filledSlots.acquire();
      removeFromBuffer();
      emptySlots.release();
  }

