        // 在输出前先加锁，确保这段输出不会被其他线程插入
        std::lock_guard&lt;std::mutex&gt; lg(cout_mtx);
        std::cout &lt;&lt; "Worker " &lt;&lt; id &lt;&lt; " 开始工作\n";
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(100 * id));
