&nbsp;&nbsp;&nbsp;&nbsp;Queuequeue&nbsp;=&nbsp;new&nbsp;LinkedList&lt;&gt;();
&nbsp;&nbsp;&nbsp;&nbsp;queue.offer(root);
&nbsp;&nbsp;&nbsp;&nbsp;while&nbsp;(!queue.isEmpty())
&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;TreeNode&nbsp;node&nbsp;=&nbsp;queue.poll();
