&nbsp;&nbsp;&nbsp;&nbsp;num_str&nbsp;=&nbsp;str(num)&nbsp;#&nbsp;判断字符串是否回文&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;num_str&nbsp;==&nbsp;num_str[::-1]&nbsp;#&nbsp;测试示例&nbsp;
print(is_palindrome(12321))&nbsp;#&nbsp;True&nbsp;
print(is_palindrome(12345))&nbsp;#&nbsp;False&nbsp;
方法二：通过数学运算来实现&nbsp;


def&nbsp;is_palindrome(num):&nbsp;#&nbsp;特判：负数不是回文数&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;num&nbsp;&lt;&nbsp;0:&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;False&nbsp;#&nbsp;获取数字的位数&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;div&nbsp;=&nbsp;1&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;while&nbsp;num&nbsp;//&nbsp;div&nbsp;&gt;=&nbsp;10:&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;div&nbsp;*=&nbsp;10&nbsp;#&nbsp;判断数字的左右两侧是否相等&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;while&nbsp;num&nbsp;&gt;&nbsp;0:&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;left&nbsp;=&nbsp;num&nbsp;//&nbsp;div&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;right&nbsp;=&nbsp;num&nbsp;%&nbsp;10&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;left&nbsp;!=&nbsp;right:&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;False&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;num&nbsp;=&nbsp;(num&nbsp;%&nbsp;div)&nbsp;//&nbsp;10&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;div&nbsp;//=&nbsp;100&nbsp;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;True&nbsp;
#&nbsp;测试示例&nbsp;
