在C++中，我们可以通过重载new和delete运算符来控制内存的分配和释放。在这个基础上，我们可以实现一个只能在栈中分配空间的类和一个只能在堆中分配空间的类。
以下是一个只能在栈中分配空间的类的示例代码：
class&nbsp;StackOnly
{
public:
&nbsp;&nbsp;&nbsp;&nbsp;void&nbsp;*operator&nbsp;new(size_t)&nbsp;=&nbsp;delete;&nbsp;//&nbsp;禁用new操作符
&nbsp;&nbsp;&nbsp;&nbsp;void&nbsp;*operator&nbsp;new[](size_t)&nbsp;=&nbsp;delete;
};
int&nbsp;main()
{&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;在栈中创建对象
&nbsp;&nbsp;&nbsp;&nbsp;StackOnly&nbsp;stackObject;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;在堆中创建对象，会编译错误&nbsp;//
&nbsp;&nbsp;&nbsp;&nbsp;StackOnly&nbsp;*heapObject&nbsp;=&nbsp;new&nbsp;StackOnly();&nbsp;//
&nbsp;&nbsp;&nbsp;&nbsp;delete&nbsp;heapObject;
&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;0;
}
以上代码中，我们通过在类中禁用new操作符来防止在堆中分配空间。在main函数中，我们可以在栈中创建StackOnly对象，但是在堆中创建对象时会编译错误。
下面是一个只能在堆中分配空间的类的示例代码：
class&nbsp;HeapOnly
{
public:
&nbsp;&nbsp;&nbsp;&nbsp;void&nbsp;*operator&nbsp;new(size_t)
&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;重载new操作符
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;malloc(sizeof(HeapOnly));&nbsp;//&nbsp;在堆中分配空间
&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;void&nbsp;*operator&nbsp;new[](size_t)
&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;//&nbsp;重载new[]操作符
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;malloc(sizeof(HeapOnly));
&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;void&nbsp;operator&nbsp;delete(void&nbsp;*p)
&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;重载delete操作符
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;free(p);&nbsp;//&nbsp;释放堆空间
&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;void&nbsp;operator&nbsp;delete[](void&nbsp;*p)
&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;//&nbsp;重载delete[]操作符
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;free(p);
&nbsp;&nbsp;&nbsp;&nbsp;}
};
int&nbsp;main()
{&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;在堆中创建对象
&nbsp;&nbsp;&nbsp;&nbsp;HeapOnly&nbsp;*heapObject&nbsp;=&nbsp;new&nbsp;HeapOnly();&nbsp;//&nbsp;在栈中创建对象，会编译错误&nbsp;//
&nbsp;&nbsp;&nbsp;&nbsp;HeapOnly&nbsp;stackObject;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//
&nbsp;&nbsp;&nbsp;&nbsp;delete&nbsp;&amp;stackObject;
&nbsp;&nbsp;&nbsp;&nbsp;delete&nbsp;heapObject;
&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;0;
}
以上代码中，我们通过重载new和delete操作符来控制在堆中分配和释放空间。在main函数中，我们可以在堆中创建HeapOnly对象，但是在栈中创建对象时会编译错误。同时，我们需要手动调用delete操作符来释放堆空间。

malloc()是一个C/C++中的内存分配函数，用于在堆上动态地分配内存。以下是一个简单的实现：
typedef&nbsp;struct&nbsp;_mem_block
{
&nbsp;&nbsp;&nbsp;&nbsp;size_t&nbsp;size;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;分配的内存块大小（不包括头部）
&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;free;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;是否空闲
&nbsp;&nbsp;&nbsp;&nbsp;struct&nbsp;_mem_block&nbsp;*next;&nbsp;//&nbsp;下一个内存块
}&nbsp;mem_block;
mem_block&nbsp;*head&nbsp;=&nbsp;nullptr;&nbsp;//&nbsp;内存块链表头指针
//&nbsp;分配内存
void&nbsp;*malloc(size_t&nbsp;size)
{
&nbsp;&nbsp;&nbsp;&nbsp;mem_block&nbsp;*block,&nbsp;*last;
&nbsp;&nbsp;&nbsp;&nbsp;void&nbsp;*result;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;对齐到&nbsp;8&nbsp;字节
&nbsp;&nbsp;&nbsp;&nbsp;size&nbsp;=&nbsp;(size&nbsp;+&nbsp;7)&nbsp;&amp;&nbsp;~7;&nbsp;//&nbsp;查找可用内存块
&nbsp;&nbsp;&nbsp;&nbsp;last&nbsp;=&nbsp;nullptr;
&nbsp;&nbsp;&nbsp;&nbsp;for&nbsp;(block&nbsp;=&nbsp;head;&nbsp;block&nbsp;!=&nbsp;nullptr;&nbsp;last&nbsp;=&nbsp;block,&nbsp;block&nbsp;=&nbsp;block-&gt;next)
&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(block-&gt;free&nbsp;&amp;&amp;&nbsp;block-&gt;size&nbsp;&gt;=&nbsp;size)
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;//&nbsp;找到合适的内存块
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;block-&gt;free&nbsp;=&nbsp;0;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;result&nbsp;=&nbsp;(void&nbsp;*)(block&nbsp;+&nbsp;1);
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(block-&gt;size&nbsp;-&nbsp;size&nbsp;&gt;=&nbsp;sizeof(mem_block))
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;//&nbsp;剩余空间足够大，可以切割出新的内存块
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;mem_block&nbsp;*new_block&nbsp;=&nbsp;(mem_block&nbsp;*)((char&nbsp;*)block&nbsp;+&nbsp;sizeof(mem_block)&nbsp;+&nbsp;size);
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;new_block-&gt;size&nbsp;=&nbsp;block-&gt;size&nbsp;-&nbsp;size&nbsp;-&nbsp;sizeof(mem_block);
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;new_block-&gt;free&nbsp;=&nbsp;1;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;new_block-&gt;next&nbsp;=&nbsp;block-&gt;next;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;block-&gt;next&nbsp;=&nbsp;new_block;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;block-&gt;size&nbsp;=&nbsp;size;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(last&nbsp;!=&nbsp;nullptr&nbsp;&amp;&amp;&nbsp;last-&gt;free)
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;//&nbsp;合并前一个空闲内存块
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;last-&gt;size&nbsp;+=&nbsp;sizeof(mem_block)&nbsp;+&nbsp;block-&gt;size;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;last-&gt;next&nbsp;=&nbsp;block-&gt;next;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;block&nbsp;=&nbsp;last;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;result;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;}&nbsp;//&nbsp;找不到可用内存块，分配新的内存块
&nbsp;&nbsp;&nbsp;&nbsp;block&nbsp;=&nbsp;(mem_block&nbsp;*)sbrk(sizeof(mem_block)&nbsp;+&nbsp;size);
&nbsp;&nbsp;&nbsp;&nbsp;block-&gt;size&nbsp;=&nbsp;size;
&nbsp;&nbsp;&nbsp;&nbsp;block-&gt;free&nbsp;=&nbsp;0;
&nbsp;&nbsp;&nbsp;&nbsp;block-&gt;next&nbsp;=&nbsp;nullptr;
&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(last&nbsp;!=&nbsp;nullptr)
&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;last-&gt;next&nbsp;=&nbsp;block;
&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;else
&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;head&nbsp;=&nbsp;block;
&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;(void&nbsp;*)(block&nbsp;+&nbsp;1);
}

函数的功能是在一个字符串中查找另一个字符串，并返回第一次出现的位置。以下是一种可能的实现方式：
char&nbsp;*my_strstr(char&nbsp;*str1,&nbsp;char&nbsp;*str2)
{
&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(*str2&nbsp;==&nbsp;'\0')
&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;str1;
&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;char&nbsp;*p1&nbsp;=&nbsp;str1;
&nbsp;&nbsp;&nbsp;&nbsp;while&nbsp;(*p1&nbsp;!=&nbsp;'\0')
&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;char&nbsp;*p1_start&nbsp;=&nbsp;p1;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;char&nbsp;*p2&nbsp;=&nbsp;str2;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;while&nbsp;(*p1&nbsp;!=&nbsp;'\0'&nbsp;&amp;&amp;&nbsp;*p2&nbsp;!=&nbsp;'\0'&nbsp;&amp;&amp;&nbsp;*p1&nbsp;==&nbsp;*p2)
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;p1++;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;p2++;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(*p2&nbsp;==&nbsp;'\0')
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;p1_start;
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;p1&nbsp;=&nbsp;p1_start&nbsp;+&nbsp;1;
&nbsp;&nbsp;&nbsp;&nbsp;}
&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;nullptr;
}
