public&nbsp;class&nbsp;QuickSort
{
public&nbsp;void&nbsp;quickSort(int[]&nbsp;arr,&nbsp;int&nbsp;left,&nbsp;int&nbsp;right)
&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(left&nbsp;&lt;&nbsp;right)
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;pivot&nbsp;=&nbsp;partition(arr,&nbsp;left,&nbsp;right);
