堆排序是一种基于堆数据结构的排序算法，具体实现如下：
将原始数组构建成大根堆（或小根堆）。
将堆顶元素（即最大值或最小值）与数组的最后一个元素交换位置，此时数组的最后一个位置即为当前最大值（或最小值）。
将除最后一个元素外的数组再次构建成大根堆（或小根堆）。
重复步骤2和步骤3，直到整个数组有序。
具体实现代码如下：&nbsp;
void&nbsp;heapify(int&nbsp;arr[],&nbsp;int&nbsp;n,&nbsp;int&nbsp;i)
{
&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;largest&nbsp;=&nbsp;i;
&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;初始化堆顶为最大值
&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;left&nbsp;=&nbsp;2&nbsp;*&nbsp;i&nbsp;+&nbsp;1;
&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;左子节点
&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;right&nbsp;=&nbsp;2&nbsp;*&nbsp;i&nbsp;+&nbsp;2;
&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;右子节点
&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;如果左子节点比根节点大，则交换它们的位置
&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(left&nbsp;&lt;&nbsp;n&nbsp;&amp;&amp;&nbsp;arr[left]&nbsp;&gt;&nbsp;arr[largest])
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;largest&nbsp;=&nbsp;left;
&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;如果右子节点比根节点大，则交换它们的位置
&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(right&nbsp;&lt;&nbsp;n&nbsp;&amp;&amp;&nbsp;arr[right]&nbsp;&gt;&nbsp;arr[largest])
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;largest&nbsp;=&nbsp;right;
&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;如果最大值不是根节点，则交换它们的位置
&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(largest&nbsp;!=&nbsp;i)
&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;swap(arr[i],&nbsp;arr[largest]);
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;heapify(arr,&nbsp;n,&nbsp;largest);
&nbsp;&nbsp;&nbsp;&nbsp;}
}
void&nbsp;heapSort(int&nbsp;arr[],&nbsp;int&nbsp;n)
{
&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;构建大根堆
&nbsp;&nbsp;&nbsp;&nbsp;for&nbsp;(int&nbsp;i&nbsp;=&nbsp;n&nbsp;/&nbsp;2&nbsp;-&nbsp;1;&nbsp;i&nbsp;&gt;=&nbsp;0;&nbsp;i--)
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;heapify(arr,&nbsp;n,&nbsp;i);&nbsp;//&nbsp;依次取出堆顶元素，并进行排序
&nbsp;&nbsp;&nbsp;&nbsp;for&nbsp;(int&nbsp;i&nbsp;=&nbsp;n&nbsp;-&nbsp;1;&nbsp;i&nbsp;&gt;=&nbsp;0;&nbsp;i--)
&nbsp;&nbsp;&nbsp;&nbsp;{
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;swap(arr[0],&nbsp;arr[i]);&nbsp;//&nbsp;将堆顶元素与当前未排序的最后一个元素交换
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;heapify(arr,&nbsp;i,&nbsp;0);&nbsp;&nbsp;&nbsp;//&nbsp;将除最后一个元素外的数组再次构建成大根堆
&nbsp;&nbsp;&nbsp;&nbsp;}
}


	其中，heapify函数是用来构建堆的，heapSort函数是堆排序的入口函数。时间复杂度为O(nlogn)，空间复杂度为O(1)。

